import React, { useEffect, useState } from "react";
import Slider from "react-slick";

// Import css files
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";


function CarouselPropertyUnits({
  prescription,
  setopenRequiredQuantityModal,
  setselectedWholesalerReceipt,
}) {
  console.log("pescription", prescription);
  const [nav1, setNav1] = useState(null);
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slider1, setSlider1] = useState(null);
  useEffect(() => {
    setNav1(slider1);
  }, [slider1]);

  const settings = {
    dots: true,
    speed: 1000,
    slidesToShow: 2,
    slidesToScroll: 1,
    infinite: true,
    autoplay: true,
    onReInit: () => setCurrentSlide(slider1?.innerSlider.state.currentSlide),
    autoplaySpeed: 1000,
    lazyLoad: true,
    asNavFor: ".slider-nav",
    focusOnSelect: true,
    nextArrow: (
      <div>
        <div className="next-slick-arrow">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            stroke="black"
            height="24"
            viewBox="0 -960 960 960"
            width="24"
          >
            <path d="m242-200 200-280-200-280h98l200 280-200 280h-98Zm238 0 200-280-200-280h98l200 280-200 280h-98Z" />
          </svg>
        </div>
      </div>
    ),
    prevArrow: (
      <div>
        <div className="next-slick-arrow rotate-180">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            stroke="black"
            height="24"
            viewBox="0 -960 960 960"
            width="24"
          >
            <path d="m242-200 200-280-200-280h98l200 280-200 280h-98Zm238 0 200-280-200-280h98l200 280-200 280h-98Z" />
          </svg>
        </div>
      </div>
    ),
    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 2,
        },
      },
      {
        breakpoint: 600,
        settings: {
          slidesToShow: 1,
        },
      },
    ],
  };

  const handleSelectImage = (item) => {
    setopenRequiredQuantityModal(true);
    setselectedWholesalerReceipt(item.wholesaler_receipt);
  };

  return (
    <>
      <div className="content bg-gray-100 max-h-[440px]">
        <p className="header">Price Discounts</p>
        <div className="container">
          <Slider
            {...settings}
            asNavFor={nav1}
            ref={(slider) => setSlider1(slider)}
          >
            {prescription?.images.map((item) => (
              <div
                key={item.id}
                className=" shadow-lg rounded-md mx-3"
                onClick={() => handleSelectImage(item)}
              >
                <div className=" m-2 ">
                  <img
                    className="w-full"
                    style={{ height: 200 }}
                    src={
                      item.image 
                        ? item.image
                        : ""
                    }
                    alt=""
                  />
                  <p className="mt-2 font-semibold text-sm capitalize">
                    {prescription.patient_name}
                  </p>
                  <p className="mt-2 font-bold text-sm capitalize">
                    {prescription.patient_name}
                  </p>
                </div>
              </div>
            ))}
          </Slider>
          <div style={{ height: 75, width: 100 }} className="thumb-wrapper">
            {prescription?.images.map((item, idx) => (
              <div
                key={item.id}
                className={currentSlide === idx ? "active" : null}
                onClick={() => {
                  slider1?.slickGoTo(idx);
                }}
              >
                <img
                  src={
                    item.images &&
                      item.images.length
                      ? item.images[0].image
                      : ""
                  }
                  alt={item.patient_name}
                />
                {currentSlide}
                <p>{item.patient_name}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </>
  );
}

export default CarouselPropertyUnits;
